# Private browser-only ledger: HTML, CSS and JS embedded as source literals.
HTML = "<section id=\"actualPurchasePanel\"><h2>購入した馬券と回収率</h2><p class=\"muted\">上で保存した3連単の下書きから、実際に購入した分だけ記録します。JRAの購入履歴や結果との自動照合はありません。</p><label for=\"realUnit\">1点あたり実際の購入額（円）</label><input id=\"realUnit\" type=\"number\" min=\"100\" max=\"100000\" step=\"100\" inputmode=\"numeric\" value=\"100\"><button id=\"realAdd\" disabled>このレースの購入済み馬券を記録</button><p class=\"muted\">「保存済み下書き」の日付・競馬場・Rを使います。下書きを作っただけでは購入記録になりません。</p><div class=\"ledger-stats\"><div>確定分の投資<strong id=\"realInvest\">0円</strong></div><div>確定分の払戻<strong id=\"realReturn\">0円</strong></div><div>回収率<strong id=\"realROI\">—</strong></div><div>確定収支<strong id=\"realProfit\">0円</strong></div></div><p id=\"realPending\" class=\"muted\">払戻未確定の購入額：0円</p><h3>選択した日付の実戦記録</h3><p class=\"muted\">下の数字は選択した日付のみ。上の回収率は全期間の確定分です。</p><div class=\"ledger-stats day-ledger-stats\"><div>当日の確定投資<strong id=\"realDayInvest\">0円</strong></div><div>当日の確定払戻<strong id=\"realDayReturn\">0円</strong></div><div>当日の回収率<strong id=\"realDayROI\">—</strong></div><div>当日の確定収支<strong id=\"realDayProfit\">0円</strong></div></div><p id=\"realDayPending\" class=\"muted\">当日の払戻待ち：0件</p><h3>月別・競馬場別の実戦振り返り</h3><p class=\"muted\">本人が入力した購入記録を集計。払戻待ちは投資額を別表示し、確定回収率には含めません。勝率・予想的中率やJRA照合済みを意味しません。</p><h4>月別</h4><div id=\"realMonthSummary\" class=\"real-analysis\" role=\"region\" aria-label=\"月別の本人入力収支\"></div><h4>競馬場別</h4><div id=\"realTrackSummary\" class=\"real-analysis\" role=\"region\" aria-label=\"競馬場別の本人入力収支\"></div><h3>3連単の結果振り返り（本人入力）</h3><p class=\"muted\">購入記録ごとに1〜3着を手入力して、買い目に含まれていたかを照合。JRA結果の自動取得やAI予想の精度判定ではありません。払戻額も自動変更しません。着順の修正時は入力を空欄にするとメモを解除できます。</p><div id=\"realReviewSummary\" class=\"real-review-summary\" role=\"status\">結果メモを集計しています。</div><label class=\"pending-filter\" for=\"realPendingOnly\"><input id=\"realPendingOnly\" type=\"checkbox\">未確定の馬券だけ表示</label><div id=\"realList\" role=\"region\" aria-label=\"購入した馬券の自己申告記録\"></div><p id=\"realMessage\" class=\"muted\" role=\"status\">実際に購入した分だけ記録してください。</p><label for=\"realImport\">JSONバックアップから実戦購入記録を復元</label><input id=\"realImport\" type=\"file\" accept=\".json,application/json\"><p class=\"muted\">復元すると現在の購入記録を確認後に全件置換します。今の記録を先にバックアップしてください。JRAの購入履歴の照合ではありません。JSONは端末内でのみ読みます。</p><button id=\"realExport\" class=\"secondary\">実戦購入記録をJSONでバックアップ</button><p class=\"muted\">保存先はこのブラウザーの端末内のみ。ブラウザー・端末を変えると記録が引き継がれない場合があります。購入未確定分は回収率から除外。既存の別ページの実戦記録とも自動合算しません。</p></section>"
CSS = ".ledger-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:15px 0}.ledger-stats>div{padding:12px 9px;background:#0c2239;border:1px solid #3c5671;border-radius:10px;font-size:12px;color:#cfdeef}.ledger-stats strong{display:block;font-size:21px;color:#fff;font-variant-numeric:tabular-nums}.real-entry{padding:13px 0;border-bottom:1px solid #49627d}.real-entry strong{display:block}.real-entry button{min-height:42px;margin-right:8px}.real-entry button.secondary{background:#304d6e}.real-entry p{margin:9px 0}#realAdd,#realExport{width:100%}.day-ledger-stats{margin:10px 0}.pending-filter{display:flex;align-items:center;gap:10px;margin:12px 0;padding:10px 12px;border:1px solid #49627d;border-radius:10px;font-size:14px}.pending-filter input{width:21px;height:21px;min-height:21px;padding:0;flex:0 0 auto;accent-color:#edca70}.real-analysis{margin:9px 0 17px}.real-analysis-row{background:#102841;border:1px solid #3c5671;border-radius:10px;padding:10px 12px;margin:8px 0}.real-analysis-row strong{display:block;color:#f4d485;font-size:16px}.real-analysis-row p{font-size:13px;color:#d1dfec;line-height:1.6;margin:4px 0 0;overflow-wrap:anywhere}.real-review-summary{padding:12px;margin:9px 0 15px;border:1px solid #6a7490;background:#0c2840;border-radius:10px;font-size:14px;line-height:1.8}.real-entry button.review-entry{border:1px solid #bba568;background:#243e56;color:#ffe7af}"
JS = "(()=>{'use strict';\n/* Owner-operated local-only 3連単 purchase ledger, separated from draft\n   simulations and never used to claim JRA purchase verification. */\nconst el=id=>document.getElementById(id);\nconst DRAFTS='keiba-nine-owner-ticket-drafts-v1';\nconst REAL='keiba-nine-owner-real-purchases-v1';\nconst tracks=new Set(['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉']);\nconst yen=n=>Number(n).toLocaleString('ja-JP')+'円';\nfunction validDate(s){\n if(typeof s!=='string'||!/^\\d{4}-\\d{2}-\\d{2}$/.test(s))return false;\n const t=new Date(s+'T12:00:00Z');\n return Number.isFinite(t.valueOf())&&t.toISOString().slice(0,10)===s;\n}\nfunction validNumbers(a){\n return Array.isArray(a)&&a.length<=18&&a.every(n=>\n  Number.isInteger(n)&&n>=1&&n<=18)&&new Set(a).size===a.length;\n}\nfunction combinations(first,second,third){\n const count=new Set();\n for(const a of first)for(const b of second)for(const c of third){\n  if(a!==b&&a!==c&&b!==c)count.add(a+'-'+b+'-'+c);\n }\n return count.size;\n}\nfunction validDraft(r){\n return r&&typeof r==='object'&&validDate(r.date)&&tracks.has(r.track)&&\n Number.isInteger(r.race)&&r.race>=1&&r.race<=12&&\n validNumbers(r.first)&&validNumbers(r.second)&&validNumbers(r.third)&&\n combinations(r.first,r.second,r.third)>=1&&\n combinations(r.first,r.second,r.third)<=48;\n}\nfunction validResult(result){\n return Array.isArray(result)&&result.length===3&&\n  result.every(n=>Number.isInteger(n)&&n>=1&&n<=18)&&new Set(result).size===3;\n}\nfunction readResult(text){\n const circled='①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱';\n const normalized=text.trim().replace(/[①-⑱]/g,n=>' '+(circled.indexOf(n)+1)+' ');\n if(!/^\\d{1,2}(?:[\\s,、・\\-／/]+\\d{1,2}){2}$/.test(normalized.trim()))return null;\n const result=normalized.trim().split(/[\\s,、・\\-／/]+/).map(Number);\n return validResult(result)?result:null;\n}\nfunction reviewResult(r){\n if(!validResult(r.result))return '結果未入力';\n const [a,b,c]=r.result;\n const hit=r.first.includes(a)&&r.second.includes(b)&&r.third.includes(c);\n if(hit)return '買い目に一致（3連単の組み合わせ内）';\n if(!r.first.includes(a))return '1着馬が1着候補外'+\n  ((r.second.includes(a)||r.third.includes(a))?'（他の着順候補にはあり）':'');\n if(!r.second.includes(b))return '2着馬が2着候補外';\n return '3着馬が3着候補外';\n}\nfunction validRecord(r){\n if(!validDraft(r)||typeof r.id!=='string'||r.id.length>80||\n  !/^[0-9a-z-]+$/.test(r.id)||!Number.isSafeInteger(r.unit)||\n  r.unit<100||r.unit>100000||r.unit%100!==0||\n  !Number.isSafeInteger(r.stake)||r.stake<100||\n  (r.payout!==null&&(!Number.isSafeInteger(r.payout)||r.payout<0))||\n  (Object.prototype.hasOwnProperty.call(r,'result')&&r.result!==null&&!validResult(r.result))||\n  typeof r.purchasedAt!=='string'||r.purchasedAt.length>32)return false;\n return r.stake===combinations(r.first,r.second,r.third)*r.unit;\n}\nfunction readDraft(){\n try{\n  const a=JSON.parse(localStorage.getItem(DRAFTS)||'[]');\n  if(!Array.isArray(a))return null;\n  const day=el('mDate').value,track=el('mTrack').value,race=Number(el('mRace').value);\n  const r=a.find(x=>x&&x.date===day&&x.track===track&&x.race===race);\n  return validDraft(r)?r:null;\n }catch(_){return null;}\n}\nlet real=[];\ntry{\n const raw=JSON.parse(localStorage.getItem(REAL)||'[]');\n if(Array.isArray(raw)){\n  const ids=new Set();\n  for(const p of raw.slice(-500)){\n   if(!validRecord(p)||ids.has(p.id))continue;\n   ids.add(p.id);\n   real.push({id:p.id,date:p.date,track:p.track,race:p.race,\n    first:p.first,second:p.second,third:p.third,unit:p.unit,\n    stake:p.stake,payout:p.payout,purchasedAt:p.purchasedAt,\n    result:validResult(p.result)?p.result.slice():null});\n  }\n }\n}catch(_){}\nfunction persist(){\n try{localStorage.setItem(REAL,JSON.stringify(real));return true}\n catch(_){return false}\n}\nfunction message(s){el('realMessage').textContent=s;}\nfunction summarizeBy(keyOf,hostId,chronological){\n const groups=new Map();\n for(const r of real){\n  const key=keyOf(r);\n  if(!groups.has(key))groups.set(key,{paid:0,stake:0,returned:0,pending:0,pendingStake:0});\n  const g=groups.get(key);\n  if(r.payout===null){g.pending++;g.pendingStake+=r.stake;}\n  else{g.paid++;g.stake+=r.stake;g.returned+=r.payout;}\n }\n const host=el(hostId);host.replaceChildren();\n if(!groups.size){\n  const p=document.createElement('p');p.className='muted';\n  p.textContent='購入記録はまだありません。';host.append(p);return;\n }\n const ordered=Array.from(groups.entries()).sort((a,b)=>chronological\n   ? b[0].localeCompare(a[0])\n   : b[1].stake-a[1].stake||a[0].localeCompare(b[0]));\n for(const [name,g] of ordered){\n  const row=document.createElement('div');row.className='real-analysis-row';\n  const title=document.createElement('strong');title.textContent=name;\n  const details=document.createElement('p');details.className='muted';\n  const profit=g.returned-g.stake;\n  details.textContent='確定 '+g.paid+'件｜投資 '+yen(g.stake)+\n   '｜払戻 '+yen(g.returned)+'｜収支 '+(profit>=0?'+':'')+yen(profit)+\n   '｜回収率 '+(g.stake?(100*g.returned/g.stake).toFixed(1)+'%':'—')+\n   '｜未確定 '+g.pending+'件・投資 '+yen(g.pendingStake);\n  row.append(title,details);host.append(row);\n }\n}\nfunction show(){\n const reviewed=real.filter(x=>validResult(x.result));\n const hit=reviewed.filter(x=>x.first.includes(x.result[0])&&\n   x.second.includes(x.result[1])&&x.third.includes(x.result[2]));\n const missedFirst=reviewed.filter(x=>!x.first.includes(x.result[0]));\n el('realReviewSummary').textContent='結果を入力した購入記録：'+reviewed.length+'件／'+\n   '3連単買い目に一致：'+hit.length+'件／1着候補の取りこぼし：'+missedFirst.length+\n   '件。未入力の馬券は判定しません。';\n\n el('realAdd').disabled=!readDraft();\n const paid=real.filter(x=>x.payout!==null);\n const pending=real.filter(x=>x.payout===null);\n const invested=paid.reduce((n,r)=>n+r.stake,0);\n const returned=paid.reduce((n,r)=>n+r.payout,0);\n el('realInvest').textContent=yen(invested);\n el('realReturn').textContent=yen(returned);\n el('realROI').textContent=invested?(100*returned/invested).toFixed(1)+'%':'—';\n el('realProfit').textContent=(returned-invested>=0?'+':'')+yen(returned-invested);\n el('realPending').textContent='払戻未確定：'+pending.length+'件・投資 '+\n  yen(pending.reduce((n,r)=>n+r.stake,0))+'（回収率から除外）';\n const host=el('realList');host.replaceChildren();\n const day=real.filter(r=>r.date===el('mDate').value);\n const dayPaid=day.filter(r=>r.payout!==null);\n const dayPending=day.filter(r=>r.payout===null);\n const dayStake=dayPaid.reduce((n,r)=>n+r.stake,0);\n const dayReturned=dayPaid.reduce((n,r)=>n+r.payout,0);\n el('realDayInvest').textContent=yen(dayStake);\n el('realDayReturn').textContent=yen(dayReturned);\n el('realDayROI').textContent=dayStake?(100*dayReturned/dayStake).toFixed(1)+'%':'—';\n el('realDayProfit').textContent=(dayReturned-dayStake>=0?'+':'')+yen(dayReturned-dayStake);\n el('realDayPending').textContent='当日の払戻待ち：'+dayPending.length+'件・投資 '+\n  yen(dayPending.reduce((n,r)=>n+r.stake,0))+'（確定回収率から除外）';\n summarizeBy(r=>r.date.slice(0,7),'realMonthSummary',true);\n summarizeBy(r=>r.track,'realTrackSummary',false);\n const visible=el('realPendingOnly').checked?dayPending:day;\n if(!visible.length){\n  const p=document.createElement('p');p.className='muted';\n  p.textContent=!day.length?'この日付の購入記録はありません。':'この日付に払戻待ちの馬券はありません。';host.append(p);\n }\n for(const r of visible.slice().reverse()){\n  const row=document.createElement('div');row.className='real-entry';\n  const heading=document.createElement('strong');\n  heading.textContent=r.track+r.race+'R｜3連単 '+combinations(r.first,r.second,r.third)+'点';\n  const body=document.createElement('p');body.className='muted';\n  body.textContent='1着 '+r.first.join('・')+'／2着 '+r.second.join('・')+\n   '／3着 '+r.third.join('・')+'｜投資 '+yen(r.stake)+\n   '｜払戻 '+(r.payout===null?'未確定':yen(r.payout))+\n   '｜結果 '+(validResult(r.result)?r.result.join('-'):'未入力')+\n   '｜照合：'+reviewResult(r);\n  const settle=document.createElement('button');\n  settle.textContent=r.payout===null?'払戻を入力':'払戻を修正';\n  settle.onclick=()=>{\n   const value=prompt('実際の払戻額（円）を入力。外れの場合は0円。',r.payout===null?'0':String(r.payout));\n   if(value===null)return;\n   const clean=value.trim(),num=Number(clean);\n   if(!/^\\d+$/.test(clean)||!Number.isSafeInteger(num)){\n    message('払戻額は0円以上の整数で入力してください。');return;\n   }\n   const old=r.payout;r.payout=num;\n   if(!persist()){r.payout=old;message('保存できませんでした。');return;}\n   show();message('払戻額を反映しました。確定分の回収率に加算します。');\n  };\n  const remove=document.createElement('button');remove.className='secondary';\n  remove.textContent='購入記録を削除';\n  remove.onclick=()=>{\n   if(!confirm('この購入記録を削除しますか？下書きは残ります。'))return;\n   const old=real.slice();real=real.filter(x=>x.id!==r.id);\n   if(!persist()){real=old;message('削除内容を保存できませんでした。');return;}\n   show();message('購入記録を削除しました。');\n  };\n  const review=document.createElement('button');review.className='review-entry';\n  review.textContent=validResult(r.result)?'着順を修正・空欄で解除':'実際の1〜3着を入力';\n  review.onclick=()=>{\n   const answer=prompt('JRA公式で結果を確認し、1着-2着-3着の馬番を入力してください（例：1-2-3）。入力値は本人メモで、JRAと自動照合しません。',\n     validResult(r.result)?r.result.join('-'):'');\n   if(answer===null)return;\n   if(answer.trim()===''&&validResult(r.result)){\n    if(!confirm('この購入記録の着順メモだけを未入力に戻しますか？購入額・払戻額は残ります。'))return;\n    const old=r.result;r.result=null;\n    if(!persist()){r.result=old;message('保存できませんでした。');return;}\n    show();message('着順メモを未入力に戻しました。購入記録はそのままです。');return;\n   }\n   const parsed=readResult(answer);\n   if(!parsed){message('異なる3頭の馬番（1〜18）を「1-2-3」の形式で入力してください。');return;}\n   if(!confirm(r.date+' '+r.track+r.race+'Rの結果メモを'+parsed.join('→')+\n     'で保存しますか？JRA公式での確認が必要です。'))return;\n   const old=r.result;r.result=parsed;\n   if(!persist()){r.result=old;message('保存できませんでした。');return;}\n   show();message('着順メモを保存しました。払戻額は変更していません。');\n  };\n  row.append(heading,body,settle,remove,review);host.append(row);\n }\n}\nel('realUnit').value='100';\nel('realPendingOnly').onchange=show;\nel('realAdd').onclick=()=>{\n const draft=readDraft();\n const value=el('realUnit').value.trim(),unit=Number(value);\n if(!draft){message('先にこのレースの3連単下書きを保存してください。');return;}\n if(!/^\\d+$/.test(value)||!Number.isSafeInteger(unit)||\n    unit<100||unit>100000||unit%100!==0){\n  message('1点あたり100円単位で入力してください。');return;\n }\n const points=combinations(draft.first,draft.second,draft.third);\n const stake=points*unit;\n if(!Number.isSafeInteger(stake)||real.length>=500){\n  message('保存可能な購入記録数または金額を超えました。');return;\n }\n const duplicate=real.some(x=>x.date===draft.date&&x.track===draft.track&&x.race===draft.race&&\n  x.unit===unit&&JSON.stringify(x.first)===JSON.stringify(draft.first)&&\n  JSON.stringify(x.second)===JSON.stringify(draft.second)&&\n  JSON.stringify(x.third)===JSON.stringify(draft.third));\n const explain=(duplicate?'同じ買い目の購入記録があります。別の実購入分ですか？\\n':'')+\n  draft.date+' '+draft.track+draft.race+'R 3連単 '+points+'点 × '+yen(unit)+\n  ' ＝ '+yen(stake)+' を実際に購入しましたか？\\n下書きだけならキャンセルしてください。';\n if(!confirm(explain))return;\n const purchase={id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,13),\n  date:draft.date,track:draft.track,race:draft.race,first:draft.first.slice(),\n  second:draft.second.slice(),third:draft.third.slice(),unit,stake,payout:null,result:null,\n  purchasedAt:new Date().toISOString()};\n const previous=real.slice();real.push(purchase);\n if(!persist()){real=previous;message('端末に保存できません。ストレージ設定を確認してください。');return;}\n show();message('実際に購入した分として記録しました。払戻は未確定です。');\n};\nel('realExport').onclick=()=>{\n if(!real.length){message('バックアップする実戦記録がありません。');return;}\n try{\n  const data={format:'keiba-nine-real-3rentan-v1',\n   exportedAt:new Date().toISOString(),records:real};\n  const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});\n  const url=URL.createObjectURL(blob),a=document.createElement('a');\n  a.href=url;a.download='keiba-nine-real-3rentan.json';a.click();\n  URL.revokeObjectURL(url);message('実戦記録のバックアップを書き出しました。');\n }catch(_){message('このブラウザでは出力できません。Safariでお試しください。');}\n};\nfor(const id of ['mDate','mTrack','mRace','mSave']){\n const node=el(id),old=node.onchange||node.onclick;\n const event=id==='mSave'?'onclick':'onchange';\n node[event]=()=>{if(typeof old==='function')old();show();};\n}\n\nel('realImport').onchange=async()=>{\n const picker=el('realImport'),file=picker.files&&picker.files[0];\n if(!file)return;\n try{\n  if(!Number.isSafeInteger(file.size)||file.size<1||file.size>1024*1024)\n   throw new Error('ファイルサイズが不正です（上限1MB）。');\n  const data=JSON.parse(await file.text()),raw=data&&data.records;\n  if(!data||data.format!=='keiba-nine-real-3rentan-v1'||\n     !Array.isArray(raw)||raw.length<1||raw.length>500||\n     !raw.every(validRecord))\n   throw new Error('実戦購入記録のバックアップ形式か内容が正しくありません。');\n  if(new Set(raw.map(r=>r.id)).size!==raw.length)\n   throw new Error('購入記録IDが重複しているため復元できません。');\n  const restored=raw.map(r=>({id:r.id,date:r.date,track:r.track,race:r.race,\n   first:r.first.slice(),second:r.second.slice(),third:r.third.slice(),\n   unit:r.unit,stake:r.stake,payout:r.payout,purchasedAt:r.purchasedAt,\n   result:validResult(r.result)?r.result.slice():null}));\n  if(!confirm('現在の購入記録 '+real.length+'件を、バックアップ '+restored.length+\n    '件で全件置き換えます。今の購入記録を保存済みですか？'))return;\n  const previous=real;real=restored;\n  if(!persist()){\n   real=previous;message('端末へ保存できず、元の購入記録はそのままです。');return;\n  }\n  show();message('実戦購入記録 '+restored.length+'件を復元しました。払戻も自己申告値です。');\n }catch(err){message('復元できません：'+(err instanceof Error?err.message:'ファイルを確認してください。'));}\n finally{picker.value='';}\n};\nconst draftImport=el('mImport'),oldDraftImport=draftImport.onchange;\ndraftImport.onchange=async()=>{\n if(typeof oldDraftImport==='function')await oldDraftImport();\n show();\n};\nshow();\n})();"
